const body = $input.first().json.body;
const query = body.query;
const context = body.context || [];
const history = body.conversationHistory || [];
const userName = body.userName || 'User';

let contextText = `## Portfolio Overview for ${userName}\n`;
contextText += `Total Jobs: ${context.length}\n\n`;

context.forEach((job, idx) => {
  contextText += `### Job ${idx + 1}: ${job.projectName} (ID: ${job.jobId})\n`;
  contextText += `Mode: ${job.mode} | Created: ${job.createdAt}\n`;
  if (job.approvalStatus) {
    contextText += `Status: ${job.approvalStatus}`;
    if (job.approvedBy) contextText += ` by ${job.approvedBy}`;
    contextText += '\n';
  }
  if (job.summary) {
    contextText += `Summary: ${job.summary.substring(0, 200)}\n`;
  }
  if (job.tasks && job.tasks.length > 0) {
    const openTasks = job.tasks.filter(t => t.status === 'open' || t.status === 'in_progress');
    contextText += `Tasks: ${job.tasks.length} total (${openTasks.length} open)\n`;
    job.tasks.slice(0, 10).forEach(t => {
      contextText += `  - [${t.status}] ${t.title} (${t.priority})\n`;
    });
  }
  if (job.issues && job.issues.length > 0) {
    contextText += `Issues: ${job.issues.length}\n`;
    job.issues.slice(0, 5).forEach(i => {
      contextText += `  - ${i.title}${i.severity ? ' [' + i.severity + ']' : ''}\n`;
    });
  }
  if (job.changeOrders && job.changeOrders.length > 0) {
    contextText += `Change Orders: ${job.changeOrders.length}\n`;
  }
  contextText += '\n';
});

let historyText = '';
if (history.length > 0) {
  historyText = '\n## Previous Conversation\n';
  history.forEach(h => {
    historyText += `${h.role === 'user' ? 'User' : 'Assistant'}: ${h.content}\n`;
  });
}

const fullContext = contextText + historyText;

return { context: fullContext, question: query, jobCount: context.length };

// Extract AI response from Gemini LangChain node
// The node returns: {"parts":[{"text":"..."}],"role":"model"}
const input = $input.first().json;

function extractText(obj) {
  if (!obj) return '';
  if (typeof obj === 'string') return obj;
  // Gemini format: {parts:[{text:'...'}], role:'model'}
  if (obj.parts && Array.isArray(obj.parts)) {
    return obj.parts.map(p => p.text || '').join('');
  }
  if (obj.text) return typeof obj.text === 'string' ? obj.text : extractText(obj.text);
  if (obj.output) return typeof obj.output === 'string' ? obj.output : extractText(obj.output);
  if (obj.response) return typeof obj.response === 'string' ? obj.response : extractText(obj.response);
  if (obj.content) return typeof obj.content === 'string' ? obj.content : extractText(obj.content);
  if (obj.message && obj.message.content) return obj.message.content;
  if (obj.candidates) {
    try { return obj.candidates[0].content.parts[0].text; } catch(e) {}
  }
  return JSON.stringify(obj);
}

const aiResponse = extractText(input) || 'Sorry, I could not generate a response.';

return {
  answer: aiResponse,
  sources: [],
  mode: 'portfolio',
  processedAt: new Date().toISOString()
};
